#!/system/bin/sh
# ============================================================
#  kdrw.sh —— 一次性内核读写，执行即装载，重启即失效
#
#    sh kdrw.sh            装载
#    sh kdrw.sh --status   自检（模块在不在、隐藏没隐藏）
#    sh kdrw.sh --off      卸载（模块未隐藏时有效）
#
#  不写 /data/adb/modules、不改 boot、不落任何开机自启，
#  重启后内核里什么都不剩。
# ============================================================
KO=/data/local/tmp/kdrw.ko
SENT_OFF=8368

if [ "$1" = "--off" ]; then
	rmmod msm_perf_mon 2>/dev/null && echo "已卸载" || echo "没在跑（或已隐藏）"
	exit 0
fi

if [ "$1" = "--status" ]; then
	echo "modules: $(grep -c msm_perf_mon /proc/modules 2>/dev/null)"
	echo "sysfs:   $(ls -d /sys/module/msm_perf_mon 2>/dev/null || echo '(无)')"
	echo "kallsyms:$(grep -c msm_perf_mon /proc/kallsyms 2>/dev/null)"
	echo "tainted: $(cat /proc/sys/kernel/tainted)"
	exit 0
fi

[ "$(id -u)" = "0" ] || { echo "需要 root"; exit 1; }

# 1) 释放内嵌模块
base64 -d > "$KO" <<'KDRW_KO_EOF'

KDRW_KO_EOF
chmod 644 "$KO"

# 2) v9 用 kprobe 按符号名挂钩，不需要预置任何内核地址。
#    哨兵保留（pack.sh 靠它定位回填点），但这次不用写。
echo "通道：kprobe on __arm64_sys_lookup_dcookie"

# 4) 装载
if insmod "$KO"; then
	echo "装载成功"
else
	# KernelSU 的 LKM 模式有自己的一条装载路径
	if command -v ksud >/dev/null 2>&1; then
		ksud insmod "$KO" && echo "装载成功（ksud）"
	else
		echo "装载失败: $?"
		dmesg | tail -5
	fi
fi

echo "--- 状态 ---"
sh "$0" --status
echo "提示：调 kdrw_hide() 之后模块从 /proc/modules、/sys/module、/proc/kallsyms 全部消失，"
echo "      rmmod 就找不到了，恢复只能重启；模板侧 kdrw_alive() 用来判断驱动在不在。"
